    StringValue: isCredentialType(asset.valueType) ? null : asset.stringValue,
    BoolValue: asset.boolValue ?? false,
    IntValue: asset.intValue ?? 0,
    ExternalName: asset.externalName ?? "",
    CredentialStoreId: asset.credentialStoreId ?? null,
    AllowDirectApiAccess: asset.allowDirectApiAccess ?? false,
    Tags: (asset.tags ?? []).map((t) => t.name ?? ""),
    CreationTime: asset.creationTime ? new Date(asset.creationTime).toISOString() : "",
