// src/utils/job-resolver.ts
async function resolveJob(jobKey, options) {
  const [apiError, api] = await catchError(createApiClient(JobsApi, { tenant: options?.tenant }));
  if (apiError) {
    throw new Error(`Failed to create Jobs API client: ${apiError.message}`, { cause: apiError });
  }
  const [infoError, jobInfo] = await catchError(api.jobsGetJobInfo({ jobKey }));
  if (infoError) {
    const errorMessage2 = await extractErrorMessage(infoError);
    throw new Error(`Failed to look up job with key '${jobKey}': ${errorMessage2}`, { cause: infoError });
  }
  if (jobInfo.id === undefined || jobInfo.id === null) {
    throw new Error(`Job '${jobKey}' has no numeric ID — cannot resolve.`);
  }
  const [getError, job] = await catchError(api.jobsGetById({ key: jobInfo.id }));
  if (getError) {
    const errorMessage2 = await extractErrorMessage(getError);
    throw new Error(`Failed to get job details: ${errorMessage2}`, {
      cause: getError
    });
  }
  if (!jobInfo.organizationUnitId) {
    throw new Error(`Job '${jobKey}' has no folder association — cannot resolve folder context.`);
  }
  if (!job.folderKey) {
    throw new Error(`Job '${jobKey}' has no folder key — cannot resolve folder context.`);
  }
  return {
    id: jobInfo.id,
    key: jobInfo.key || jobKey,
    folderId: jobInfo.organizationUnitId,
    folderKey: job.folderKey,
    folderName: jobInfo.folderFullyQualifiedName || "",
    job
  };
}

