// src/utils/export-helper.ts
async function pollAndDownloadExport(params) {
  const {
    exportsApi,
    exportId,
    outputPath,
    entityName,
    maxAttempts = 30,
    pollIntervalMs = 2000
  } = params;
  for (let i = 0;i < maxAttempts; i++) {
    const [pollError, status] = await catchError(exportsApi.exportsGetById({ key: exportId }));
    if (pollError) {
      await reportFailure(`Error polling ${entityName} export status`, pollError);
      return null;
    }
    if (status.status === "Completed") {
      break;
    }
    if (status.status === "Failed") {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: `${entityName} export failed`,
        Instructions: "The server-side export job failed. Try again or narrow the filter criteria."
      });
      processContext.exit(1);
      return null;
    }
    if (i === maxAttempts - 1) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: `${entityName} export timed out`,
        Instructions: `Export did not complete within ${maxAttempts * pollIntervalMs / 1000}s. Export ID: ${exportId}`
      });
      processContext.exit(1);
      return null;
    }
    await new Promise((r) => setTimeout(r, pollIntervalMs));
  }
  const [linkError, downloadLink] = await catchError(exportsApi.exportsGetDownloadLinkById({ key: exportId }));
  if (linkError) {
    await reportFailure(`Error getting ${entityName} export download link`, linkError);
    return null;
  }
  if (!downloadLink.uri) {
    OutputFormatter.error({
      Result: RESULTS.Failure,
      Message: `Error getting ${entityName} export download link`,
      Instructions: "No download URI returned."
    });
    processContext.exit(1);
    return null;
  }
  const [fetchError, fileResponse] = await catchError(fetch(downloadLink.uri));
  if (fetchError || !fileResponse.ok) {
    OutputFormatter.error({
      Result: RESULTS.Failure,
      Message: `Error downloading ${entityName} export`,
      Instructions: fetchError ? fetchError.message : `HTTP ${fileResponse.status}`
    });
    processContext.exit(1);
    return null;
  }
  const [bufferError, buffer] = await catchError(fileResponse.arrayBuffer());
  if (bufferError) {
    OutputFormatter.error({
      Result: RESULTS.Failure,
      Message: `Error reading ${entityName} export data`,
      Instructions: bufferError.message
    });
    processContext.exit(1);
    return null;
  }
  const fs = getFileSystem();
  const [writeError] = await catchError(fs.writeFile(outputPath, Buffer.from(buffer)));
  if (writeError) {
    OutputFormatter.error({
      Result: RESULTS.Failure,
      Message: `Error writing ${entityName} export to disk`,
      Instructions: `Could not write to '${outputPath}': ${writeError.message}`
    });
    processContext.exit(1);
    return null;
  }
  return {
    fileName: outputPath,
    size: buffer.byteLength,
    exportId
  };
}

