function formatCredentialStoreRow(store) {
  return {
    Key: store.key || "",
    Id: store.id ?? "",
    Name: store.name || "",
    Type: store.type || "",
    HostName: store.hostName || "",
    ProxyType: store.proxyType || ""
  };
}
function formatCredentialStoreDetail(store) {
  return {
    ...formatCredentialStoreRow(store),
    AdditionalConfiguration: store.additionalConfiguration || ""
  };
}
