var registerCredentialStoresCommand = (program2) => {
  const credentialStores = program2.command("credential-stores").description("Manage Orchestrator credential stores (tenant-scoped secure storage backends for credentials and assets).");
  credentialStores.command("list").description("List all credential stores in the tenant. " + "Returns Key, Id, Name, Type, HostName, and ProxyType by default; " + "pass --all-fields for the raw DTO including details and defaultCredentialStores. " + "Use --name to filter by name. " + "Use the key with 'credential-stores get' to retrieve full details.").addOption(createHiddenDeprecatedTenantOption("-t, --tenant <tenant-name>")).option("-n, --name <name>", "Filter by name (contains match)").option("--id <id>", "Filter by credential store key (exact match)").option("-l, --limit <number>", "Number of items to return", String(DEFAULT_PAGE_SIZE)).option("--offset <number>", "Number of items to skip", "0").option("--sort-by <field>", "Sort results by field (e.g., 'Name asc', 'Id desc')", "Id desc").option("--all-fields", "Return all fields from the API response (default: curated subset)").examples(CREDENTIAL_STORES_LIST_EXAMPLES).trackedAction(processContext, async (options) => {
    const [apiError, api] = await catchError(createApiClient(CredentialStoresApi, {
      tenant: options.tenant
    }));
    if (apiError) {
      await reportFailure("Error listing credential stores", apiError);
      return;
    }
    const filters = [];
    if (options.name) {
      const sanitized = options.name.replace(/'/g, "''");
      filters.push(`contains(Name, '${sanitized}')`);
    }
    if (options.id) {
      const numericId = parseInt(options.id, 10);
      if (Number.isNaN(numericId)) {
        OutputFormatter.error({
          Result: RESULTS.Failure,
          Message: "Error listing credential stores",
          Instructions: `Invalid --id '${options.id}'. Must be a numeric key.`
        });
        processContext.exit(1);
        return;
      }
      filters.push(`Id eq ${numericId}`);
    }
    const [listError, result] = await catchError(api.credentialStoresGet({
      $filter: filters.length > 0 ? filters.join(" and ") : undefined,
      $orderby: options.sortBy,
      $top: parseInt(options.limit || String(DEFAULT_PAGE_SIZE), 10),
      $skip: parseInt(options.offset || "0", 10)
    }));
    if (listError) {
      await reportFailure("Error listing credential stores", listError);
      return;
    }
    const items = result.value ?? [];
    OutputFormatter.success({
      Result: RESULTS.Success,
      Code: "CredentialStoreList",
      Pagination: new Pagination({
        returned: items.length,
        limit: parseInt(options.limit || String(DEFAULT_PAGE_SIZE), 10),
        offset: parseInt(options.offset || "0", 10)
      }),
      Data: options.allFields ? items : items.map(formatCredentialStoreRow)
    });
  });
  credentialStores.command("get").description("Get a credential store by key. " + "Returns Key, Id, Name, Type, HostName, ProxyType, and AdditionalConfiguration by default; " + "pass --all-fields for the raw DTO including details and defaultCredentialStores. " + "Use 'credential-stores list' to retrieve the key.").argument("<key>", "Credential store key — use 'credential-stores list' to find").addOption(createHiddenDeprecatedTenantOption("-t, --tenant <tenant-name>")).option("--all-fields", "Return all fields from the API response (default: curated subset)").examples(CREDENTIAL_STORES_GET_EXAMPLES).trackedAction(processContext, async (key, options) => {
    const id = parseInt(key, 10);
    if (Number.isNaN(id)) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Error getting credential store",
        Instructions: `Invalid key '${key}'. Must be a numeric key — use 'credential-stores list' to find it.`
      });
      processContext.exit(1);
      return;
    }
    const [apiError, api] = await catchError(createApiClient(CredentialStoresApi, {
      tenant: options.tenant
    }));
    if (apiError) {
      await reportFailure("Error getting credential store", apiError);
      return;
    }
    const [getError, result] = await catchError(api.credentialStoresGetById({ key: id }));
    if (getError) {
      await reportFailure("Error getting credential store", getError);
      return;
    }
    OutputFormatter.success({
      Result: RESULTS.Success,
      Code: "CredentialStore",
      Data: options.allFields ? result : formatCredentialStoreDetail(result)
    });
  });
};

