// src/commands/queues.ts
function formatQueueRow(row) {
  return {
    Key: row.queueDefinitionKey ?? row.key ?? "",
    Id: row.id ?? "",
    Name: row.queueDefinitionName ?? row.name ?? "",
    Description: row.queueDefinitionDescription ?? row.description ?? "",
    MaxNumberOfRetries: row.queueDefinitionMaxNumberOfRetries ?? row.maxNumberOfRetries ?? 0,
    AcceptAutomaticallyRetry: row.queueDefinitionAcceptAutomaticallyRetry ?? row.acceptAutomaticallyRetry ?? false,
    RetryAbandonedItems: row.queueDefinitionRetryAbandonedItems ?? row.retryAbandonedItems ?? false,
    EnforceUniqueReference: row.queueDefinitionEnforceUniqueReference ?? row.enforceUniqueReference ?? false,
    ItemsToProcess: row.itemsToProcess ?? 0,
    ItemsInProgress: row.itemsInProgress ?? 0,
    TotalNumberOfTransactions: row.totalNumberOfTransactions ?? 0,
    FoldersCount: row.queueFoldersCount ?? row.foldersCount ?? 0
  };
}
function formatQueueDetail(q) {
  return {
    Key: q.key ?? "",
    Id: q.id ?? "",
    Name: q.name ?? "",
    Description: q.description ?? "",
    MaxNumberOfRetries: q.maxNumberOfRetries ?? 0,
    AcceptAutomaticallyRetry: q.acceptAutomaticallyRetry ?? false,
    RetryAbandonedItems: q.retryAbandonedItems ?? false,
    EnforceUniqueReference: q.enforceUniqueReference ?? false,
    Encrypted: q.encrypted ?? false,
    SlaInMinutes: q.slaInMinutes ?? 0,
    RiskSlaInMinutes: q.riskSlaInMinutes ?? 0,
    FoldersCount: q.foldersCount ?? 0,
    IsProcessInCurrentFolder: q.isProcessInCurrentFolder ?? false,
    CreationTime: q.creationTime ? new Date(q.creationTime).toISOString() : "",
    Tags: (q.tags ?? []).map((t) => t.name ?? "")
  };
}
function formatQueueFolders(result) {
  return {
    TotalFoldersCount: result.totalFoldersCount ?? 0,
    Folders: (result.accessibleFolders ?? []).map((f) => ({
      DisplayName: f.displayName ?? "",
      FullyQualifiedName: f.fullyQualifiedName ?? ""
    }))
  };
}
function formatQueueStats(s) {
  return {
    QueueDefinitionKey: s.queueDefinitionKey ?? "",
    QueueDefinitionName: s.queueDefinitionName ?? "",
    ItemsToProcess: s.itemsToProcess ?? 0,
    ItemsInProgress: s.itemsInProgress ?? 0,
    SuccessfulTransactionsNo: s.successfulTransactionsNo ?? 0,
    ApplicationExceptionsNo: s.applicationExceptionsNo ?? 0,
    BusinessExceptionsNo: s.businessExceptionsNo ?? 0,
    TotalNumberOfTransactions: s.totalNumberOfTransactions ?? 0,
    ProcessingMeanTime: s.processingMeanTime ?? 0,
    LastProcessed: s.lastProcessed ? new Date(s.lastProcessed).toISOString() : "",
    ReleaseName: s.releaseName ?? "",
    QueueFoldersCount: s.queueFoldersCount ?? 0
  };
}
