// src/utils/role-resolver.ts
async function resolveRoleGuid(roleKey) {
  const [apiError, api] = await catchError(createApiClient(RolesApi));
  if (apiError) {
    throw new Error(`Failed to create Roles API: ${apiError.message}`);
  }
  let skip = 0;
  const top = 100;
  while (true) {
    const [error, result] = await catchError(api.rolesGet({ $top: top, $skip: skip }));
    if (error) {
      throw new Error(`Failed to resolve role key '${roleKey}': ${await extractErrorMessage(error)}`, { cause: error });
    }
    const roles = result.value ?? [];
    const match = roles.find((r) => r.key === roleKey);
    if (match?.id) {
      return match.id;
    }
    if (roles.length < top) {
      break;
    }
    skip += top;
  }
  throw new Error(`Role with key '${roleKey}' not found.`);
}

// src/utils/user-resolver.ts
async function resolveUserGuid(userInput) {
  if (!isGuid(userInput)) {
    throw new Error(`Invalid user key '${userInput}'. Expected a GUID (e.g. 'xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx'). Use 'users list-available' to find user keys.`);
  }
  const [apiError, api] = await catchError(createApiClient(UsersApi));
  if (apiError) {
    throw new Error(`Failed to create Users API: ${apiError.message}`);
  }
  const [error, user] = await catchError(api.usersGetByKeyByIdentifier({ identifier: userInput }));
  if (error) {
    throw new Error(`Failed to resolve user '${userInput}': ${await extractErrorMessage(error)}`, { cause: error });
  }
  if (!user.id) {
    throw new Error(`User '${userInput}' not found.`);
  }
  return user.id;
}

