function parseTargetSpec(spec) {
  const parts = spec.split(",").map((p) => p.trim()).filter((p) => p.length > 0);
  if (parts.length === 0) {
    throw new Error("--target spec cannot be empty");
  }
  const out = {};
  for (const part of parts) {
    const eq = part.indexOf("=");
    if (eq === -1) {
      throw new Error(`Invalid --target part '${part}': expected 'key=value'`);
    }
    const key = part.slice(0, eq).trim().toLowerCase();
    const value = part.slice(eq + 1).trim();
    if (!value) {
      throw new Error(`--target field '${key}' value cannot be empty`);
    }
    switch (key) {
      case "machine":
        if (!isGuid(value)) {
          throw new Error(`Invalid machine key '${value}' in --target: must be a UUID`);
        }
        if (out.machineKey) {
          throw new Error(`--target has duplicate 'machine' field`);
        }
        out.machineKey = value;
        break;
      case "user":
        if (!isGuid(value)) {
          throw new Error(`Invalid user key '${value}' in --target: must be a UUID`);
        }
        if (out.userKey) {
          throw new Error(`--target has duplicate 'user' field`);
        }
        out.userKey = value;
        break;
      case "session": {
        const n = Number(value);
        if (!Number.isInteger(n) || n <= 0) {
          throw new Error(`Invalid session ID '${value}' in --target: must be a positive integer`);
        }
        if (out.sessionId !== undefined) {
          throw new Error(`--target has duplicate 'session' field`);
        }
        out.sessionId = n;
        break;
      }
      default:
        throw new Error(`Unknown --target field '${key}'. Expected: machine, user, session`);
    }
  }
  if (!out.machineKey && !out.userKey && out.sessionId === undefined) {
    throw new Error("--target must include at least one of: machine, user, session");
  }
  return out;
}
async function resolveMachinesByKeys(keys, tenant) {
  const api = await resolveOrReportError(createApiClient(MachinesApi, { tenant }), "Error resolving machines");
  if (api === null)
    return null;
  const result = await resolveOrReportError(api.machinesGet({
    $filter: `Key in (${keys.map((k) => `'${k}'`).join(",")})`,
    $top: keys.length
  }), "Error resolving machines");
  if (result === null)
    return null;
  const byKey = new Map;
  for (const m of result.value ?? []) {
    if (m.key && m.id != null)
      byKey.set(m.key.toLowerCase(), m.id);
  }
  for (const key of keys) {
    if (!byKey.has(key.toLowerCase())) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Machine not found",
        Instructions: `Machine with key '${key}' not found. Use 'machines list' to find machine keys.`
      });
      processContext.exit(1);
      return null;
    }
  }
  return byKey;
}
async function resolveUsersToRobotsByKeys(keys, folderId, tenant) {
  const [apiError, api] = await catchError(createApiClient(RobotsApi, {
    tenant,
    folderId: folderId.toString()
  }));
  if (apiError) {
    OutputFormatter.error({
      Result: RESULTS.Failure,
      Message: "Error resolving users",
      Instructions: apiError.message
    });
    processContext.exit(1);
    return null;
  }
  const filter = keys.map((k) => `UserKey eq ${k}`).join(" or ");
  const [getError, result] = await catchError(api.robotsGetRobotsFromFolderByFolderid({
    folderId,
    $filter: filter
  }));
  if (getError) {
    await reportFailure("Error resolving users", getError);
    return null;
  }
  const robots = (result.value ?? []).filter((r) => r.type !== "Attended" && r.type !== "AttendedStudioWeb");
  const byKey = new Map;
  for (const r of robots) {
    if (r.userKey && r.id != null) {
      byKey.set(r.userKey.toLowerCase(), r.id);
    }
  }
  for (const key of keys) {
    if (!byKey.has(key.toLowerCase())) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "User not found",
        Instructions: `No non-attended robot for user '${key}' in the target folder. Use 'users list' to find user keys.`
      });
      processContext.exit(1);
      return null;
    }
  }
  return byKey;
}
var VALID_MAPPING_MODES = ["dynamic", "strict"];
function validateTargetForMode(p, mode) {
  if (mode === "strict") {
    if (!p.machineKey || !p.userKey) {
      throw new Error("--target requires both 'machine' and 'user' in strict mode (enable on folders with 'account-machine mappings' turned on)");
    }
    return;
  }
  if (p.sessionId !== undefined && !p.machineKey) {
    throw new Error("--target with 'session' must also include 'machine' in dynamic mode");
  }
}
async function resolveTargets(specs, mode, ctx) {
  if (!VALID_MAPPING_MODES.includes(mode)) {
    OutputFormatter.error({
      Result: RESULTS.Failure,
      Message: "Invalid --mapping-mode",
      Instructions: `Must be one of: ${VALID_MAPPING_MODES.join(", ")}`
    });
    processContext.exit(1);
    return null;
  }
  const parsed = [];
  for (const spec of specs) {
    try {
      const p = parseTargetSpec(spec);
      validateTargetForMode(p, mode);
      parsed.push(p);
    } catch (e) {
      OutputFormatter.error({
        Result: RESULTS.Failure,
        Message: "Invalid --target",
        Instructions: extractErrorMessageSync(e)
      });
      processContext.exit(1);
      return null;
    }
  }
  const machineKeys = new Set;
  const userKeys = new Set;
  for (const p of parsed) {
    if (p.machineKey)
      machineKeys.add(p.machineKey.toLowerCase());
    if (p.userKey)
      userKeys.add(p.userKey.toLowerCase());
  }
  let machineByKey = new Map;
  if (machineKeys.size > 0) {
    const res = await resolveMachinesByKeys([...machineKeys], ctx.tenant);
    if (!res)
      return null;
    machineByKey = res;
  }
  let userByKey = new Map;
  if (userKeys.size > 0) {
    let folderId = ctx.folderId;
    if (folderId === undefined) {
      const [folderError, folder] = await catchError(resolveFolder({ folderPath: ctx.folderPath, folderKey: ctx.folderKey }, { tenant: ctx.tenant }));
      if (folderError || !folder || folder.id == null) {
        OutputFormatter.error({
          Result: RESULTS.Failure,
          Message: "Error resolving folder for user lookup",
          Instructions: folderError?.message ?? "--target with 'user' requires --folder-path or --folder-key"
        });
        processContext.exit(1);
        return null;
      }
      folderId = folder.id;
    }
    const res = await resolveUsersToRobotsByKeys([...userKeys], folderId, ctx.tenant);
    if (!res)
      return null;
    userByKey = res;
  }
  return parsed.map((p) => {
    const entry = {};
    if (p.machineKey) {
      entry.machineId = machineByKey.get(p.machineKey.toLowerCase());
    }
    if (p.userKey) {
      entry.robotId = userByKey.get(p.userKey.toLowerCase());
    }
    if (p.sessionId !== undefined)
      entry.sessionId = p.sessionId;
    return entry;
  });
}
async function injectQueueDefinitionKeys(triggers, ctx) {
  const ids = [
    ...new Set(triggers.map((t) => t.queueDefinitionId).filter((id) => id != null && id > 0))
  ];
  if (ids.length === 0)
    return;
  const [apiError, api] = await catchError(createApiClient(QueueDefinitionsApi, {
    tenant: ctx.tenant,
    folderPath: ctx.folderPath,
    folderKey: ctx.folderKey
  }));
  if (apiError) {
    logger.warn(`Failed to resolve queue keys: ${apiError.message}`);
    return;
  }
  const idToKey = new Map;
  const results = await Promise.all(ids.map(async (id) => {
    const [getError, queue] = await catchError(api.queueDefinitionsGetById({ key: id }));
    return { id, key: !getError ? queue?.key : undefined };
  }));
  for (const { id, key } of results) {
    if (key)
      idToKey.set(id, key);
  }
  for (const trigger of triggers) {
    if (trigger.queueDefinitionId != null) {
      const key = idToKey.get(trigger.queueDefinitionId);
      if (key) {
        trigger.queueDefinitionKey = key;
      }
    }
  }
}

// src/utils/credential-store-resolver.ts
async function resolveCredentialStore2(tenant, credentialStoreKey) {
  const [apiError, api] = await catchError(createApiClient(CredentialStoresApi, { tenant }));
  if (apiError)
    throw apiError;
  const [getError, result] = await catchError(api.credentialStoresGet({
    $filter: `Key eq ${credentialStoreKey}`,
    $top: 1
  }));
  if (getError) {
    throw new Error(await extractErrorMessage(getError), {
      cause: getError
    });
  }
  const store = result.value?.[0];
  if (!store?.id) {
    throw new Error(`Credential store with key '${credentialStoreKey}' not found. Use 'credential-stores list' to find it.`);
  }
  return store;
}

// src/commands/users.ts
function getResponseStatus(error) {
  if (typeof error !== "object" || error === null) {
    return;
  }
  const response = error.response;
  return typeof response?.status === "number" ? response.status : undefined;
}
function matchesContains(value, filter) {
  return filter === undefined || (value?.includes(filter) ?? false);
}
function hasUnattendedIntent(options) {
  return Boolean(options.unattendedUsername || options.unattendedPassword || options.credentialStoreKey || options.credentialType) || options.limitConcurrent !== undefined;
}
function validateUnattendedOptions(options, existing) {
  if (!hasUnattendedIntent(options))
    return null;
  if (existing)
    return null;
  const hasUsername = Boolean(options.unattendedUsername);
  const hasPassword = Boolean(options.unattendedPassword);
  if (hasUsername && hasPassword)
    return null;
  const missing = [
    !hasUsername && "--unattended-username",
    !hasPassword && "--unattended-password"
  ].filter((v) => typeof v === "string").join(" and ");
  return `Unattended provisioning requires ${missing}. ` + "Orchestrator silently discards an incomplete UnattendedRobot record, so the CLI refuses to submit one. " + "Provide both a Windows account and a password (or, for a read-only credential store, the external-secret name via --unattended-password) together.";
}
function buildSessionFlags(options) {
  return {
    ...options.allowUnattended && { mayHaveUnattendedSession: true },
    ...options.denyUnattended && { mayHaveUnattendedSession: false },
    ...options.allowAttended && { mayHaveRobotSession: true },
    ...options.denyAttended && { mayHaveRobotSession: false },
    ...options.allowLogin && { mayHaveUserSession: true },
    ...options.denyLogin && { mayHaveUserSession: false },
    ...options.allowPersonalWorkspace && {
      mayHavePersonalWorkspace: true
    },
    ...options.denyPersonalWorkspace && {
      mayHavePersonalWorkspace: false
    },
    ...options.active && { isActive: true },
    ...options.inactive && { isActive: false }
  };
}
async function buildUnattendedRobotBody(options, tenant, existing) {
  if (!hasUnattendedIntent(options))
    return {};
  let resolvedCredentialStoreId;
  let credentialStoreIsReadOnly = false;
  if (options.credentialStoreKey !== undefined) {
    const store = await resolveCredentialStore2(tenant, options.credentialStoreKey);
    resolvedCredentialStoreId = store.id;
    credentialStoreIsReadOnly = store.details?.isReadOnly === true;
  } else if (options.unattendedPassword && existing?.credentialStoreId !== undefined) {
    const [apiError, api] = await catchError(createApiClient(CredentialStoresApi, { tenant }));
    if (apiError)
      throw apiError;
    const [storeError, store] = await catchError(api.credentialStoresGetById({ key: existing.credentialStoreId }));
    if (storeError)
      throw storeError;
    credentialStoreIsReadOnly = store.details?.isReadOnly === true;
  }
  const passwordField = {};
  if (options.unattendedPassword) {
    if (credentialStoreIsReadOnly) {
      passwordField.credentialExternalName = options.unattendedPassword;
    } else {
      passwordField.password = options.unattendedPassword;
    }
  }
  return {
    unattendedRobot: {
      ...existing,
      ...options.unattendedUsername && {
        userName: options.unattendedUsername
      },
      ...passwordField,
      ...resolvedCredentialStoreId !== undefined && {
        credentialStoreId: resolvedCredentialStoreId
      },
      ...options.credentialType && {
        credentialType: options.credentialType
      },
      ...options.limitConcurrent !== undefined && {
        limitConcurrentExecution: options.limitConcurrent
      }
    }
  };
}
