// src/commands/webhooks.ts
function formatWebhookRow(w) {
  return {
    Key: w.key ?? "",
    Id: w.id ?? "",
    Name: w.name ?? "",
    Url: w.url ?? "",
    Enabled: w.enabled ?? false,
    SubscribeToAllEvents: w.subscribeToAllEvents ?? false,
    Events: (w.events ?? []).map((e) => e.eventType ?? "")
  };
}
function formatWebhookDetail(w) {
  return {
    ...formatWebhookRow(w),
    Description: w.description ?? "",
    AllowInsecureSsl: w.allowInsecureSsl ?? false
  };
}
async function emitWebhookError(message, error) {
  const details = await extractErrorDetails(error);
  OutputFormatter.error({
    Result: RESULTS.Failure,
    ErrorCode: details.errorCode,
    Message: message,
    Instructions: details.message,
    Retry: details.retry,
    ...details.context ? { Context: details.context } : {}
  });
  processContext.exit(1);
}
